import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import Post from '../post/Post';
import './posts.scss';

const Posts = () => {
  const [posts, setPosts] = useState([]);
  const [error, setError] = useState(null);
  const navigate = useNavigate();

  const fetchPosts = async () => {
    try {
      console.log('Posts: Fetching posts');
      const token = sessionStorage.getItem('token');
      if (!token) {
        throw new Error('No authentication token found');
      }

      const response = await fetch('http://localhost:5000/api/posts', {
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });

      if (response.status === 401) {
        console.error('Posts: Token expired or invalid');
        sessionStorage.removeItem('token');
        navigate('/login');
        return;
      }

      if (!response.ok) {
        throw new Error('Failed to fetch posts');
      }

      const data = await response.json();
      console.log('Posts: Fetched posts=', JSON.stringify(data, null, 2));
      setPosts(data);
      setError(null);
    } catch (err) {
      console.error('Posts: Error fetching posts:', err.message);
      setError(err.message || 'Failed to load posts');
    }
  };

  useEffect(() => {
    fetchPosts();

    const handleNewPost = () => {
      console.log('Posts: New post event received');
      fetchPosts();
    };

    window.addEventListener('newPost', handleNewPost);

    return () => {
      window.removeEventListener('newPost', handleNewPost);
    };
  }, []);

  return (
    <div className="posts">
      {error && <p className="error">{error}</p>}
      {posts.length === 0 && !error ? (
        <p>No posts available</p>
      ) : (
        posts.map((post) => <Post key={post._id} post={post} />)
      )}
    </div>
  );
};

export default Posts;
